import { getMitmScript } from './mitmHelper';
﻿export const dynamic = 'force-dynamic';
import { NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase';

// GET: Generate 1-click setup script for client key pointing to AntiGravity
export async function GET(request, { params }) {
  const { id } = await params;
  const { searchParams } = new URL(request.url);
  const platform = searchParams.get('platform') || 'windows';
  const mode = searchParams.get('mode') || 'config';

  const { data: keyData, error } = await supabase
    .from('client_keys')
    .select('key, label')
    .eq('id', id)
    .single();

  if (error || !keyData) {
    return new Response('Client Key not found', { status: 404 });
  }

  const clientKey = keyData.key;
  const host = request.headers.get("host") || "vinhcousera.vercel.app";
  const protocol = request.headers.get("x-forwarded-proto") || "https";
  const origin = `${protocol}://${host}`;

  if (mode === "mitm") {
    return getMitmScript(platform, clientKey, origin);
  }

  if (platform === 'windows') {
    // Generate a Windows Batch script (.bat)
    const script = `
@echo off
title AntiGravity 1-Click Configurator
echo =========================================
echo       AntiGravity 1-Click Configurator   
echo =========================================
echo.
echo Khoi tao cau hinh tu dong cho AntiGravity...

:: Create directory
set "CODEX_DIR=%USERPROFILE%\.codex"
if not exist "%CODEX_DIR%" (
    echo Dang tao thu muc: %CODEX_DIR%
    mkdir "%CODEX_DIR%"
)

:: Write config.toml
set "CONFIG_FILE=%CODEX_DIR%\config.toml"
echo Dang ghi file cau hinh tai %CONFIG_FILE%...
(
echo model_reasoning_effort = "low"
echo model_provider = "openai-custom"
echo model = "gpt-5.4"
echo.
echo [model_providers.openai-custom]
echo experimental_bearer_token = "${clientKey}"
echo name = "VinAi"
echo base_url = "${origin}/v1"
echo wire_api = "responses"
echo requires_openai_auth = false
echo supports_websockets = false
) > "%CONFIG_FILE%"

echo.
echo =========================================
echo CAU HINH ANTI-GRAVITY HOAN TAT!
echo =========================================
echo Ban bay gio da co the bat dau su dung AntiGravity (Gemini-backed) 
echo tren IDE/CLI thong qua API Gateway Vercel ma khong can chay local!
echo.
pause
`.trim().replace(/\n/g, '\r\n'); // Windows CRLF

    return new Response(script, {
      headers: {
        'Content-Type': 'application/octet-stream',
        'Content-Disposition': 'attachment; filename="setup-antigravity.bat"',
      },
    });
  } else {
    // Generate a Mac/Linux shell script (.sh)
    const script = `
#!/bin/bash
echo "========================================="
echo "       AntiGravity 1-Click Configurator  "
echo "========================================="
echo ""

CODEX_DIR="$HOME/.codex"
if [ ! -d "$CODEX_DIR" ]; then
    echo "Creating directory: $CODEX_DIR"
    mkdir -p "$CODEX_DIR"
fi

CONFIG_FILE="$CODEX_DIR/config.toml"
echo "Writing configuration to $CONFIG_FILE..."

cat << 'EOF' > "$CONFIG_FILE"
model_reasoning_effort = "low"
model_provider = "openai-custom"
model = "gpt-5.4"

[model_providers.openai-custom]
experimental_bearer_token = "${clientKey}"
name = "VinAi"
base_url = "${origin}/v1"
wire_api = "responses"
requires_openai_auth = false
supports_websockets = false
EOF

echo ""
echo "========================================="
echo "Setup AntiGravity Completed Successfully!"
echo "========================================="
echo "Your AntiGravity configuration is ready."
echo "You can now use AntiGravity (Gemini-backed) with your hosted API!"
echo ""
`.trim();

    return new Response(script, {
      headers: {
        'Content-Type': 'application/octet-stream',
        'Content-Disposition': 'attachment; filename="setup-antigravity.sh"',
      },
    });
  }
}
